#!/bin/zsh
TMUX=/opt/homebrew/bin/tmux
[ -x "$TMUX" ] || TMUX=/usr/local/bin/tmux
send() {
  local T=$1
  $TMUX send-keys -t $T C-u; sleep 1
  $TMUX send-keys -t $T "$2"; sleep 2
  $TMUX send-keys -t $T Enter; sleep 2
  $TMUX send-keys -t $T Enter; sleep 1
  echo "sent -> $T"
}

